70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        Collection<Owner> owners = this.clinicService.findAllOwners();
111	        if (DailyRegistrationLimit.isReached(owners)) {
112	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS, "Daily owner registration limit reached");
113	        }
114	        if (IdentityKey.isDuplicate(owners, owner)) {
115	            throw new RejectedRequestException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
116	        }
117	        if (CityCapacity.isFull(owners, owner)) {
118	            throw new RejectedRequestException(HttpStatus.CONFLICT, "The city is at owner capacity");
119	        }
120	        OwnerRegistration.enrich(owners, owner, ownerFieldsDto.getSharesHousehold());
121	        this.clinicService.saveOwner(owner);
122	        OwnerCreatedEvent.emit(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        owner.setDeleted(true);
154	        this.clinicService.saveOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
