20	/**
21	 * Adds idempotent-create semantics to {@code POST /api/owners}. This mapping only
22	 * matches when an {@code Idempotency-Key} header is present, so it is more specific
23	 * than {@link OwnerRestControllerV1#addOwner} (which handles the header-less case).
24	 *
25	 * <p>A first request with a given key is delegated to the normal create; the
26	 * resulting owner is remembered under that key. A repeat with an already-seen key
27	 * replays the originally created owner with {@code 200 OK} instead of creating a
28	 * duplicate.
29	 */
30	@RestController
31	@CrossOrigin(exposedHeaders = "errors, content-type")
32	@RequestMapping("/api")
33	public class IdempotentOwnerController {
34	
35	    private final OwnerRestControllerV1 delegate;
36	
37	    private final Map<String, OwnerDto> created = new ConcurrentHashMap<>();
38	
39	    public IdempotentOwnerController(OwnerRestControllerV1 delegate) {
40	        this.delegate = delegate;
41	    }
42	
43	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
44	    @PostMapping(value = "/owners", headers = "Idempotency-Key")
45	    public ResponseEntity<OwnerDto> addOwner(@RequestHeader("Idempotency-Key") String key,
46	                                             @Valid @RequestBody OwnerFieldsDto ownerFieldsDto) {
47	        OwnerDto existing = created.get(key);
48	        if (existing != null) {
49	            return new ResponseEntity<>(existing, HttpStatus.OK);
50	        }
51	        ResponseEntity<OwnerDto> response = delegate.addOwner(ownerFieldsDto);
52	        if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
53	            created.put(key, response.getBody());
54	        }
55	        return response;
56	    }
57	}
