73	    /**
74	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
75	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
76	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
77	     * the '+', else the number is rejected as invalid.
78	     */
79	    @Named("normalizeTelephone")
80	    default String normalizeTelephone(String telephone) {
81	        if (telephone == null) {
82	            return null;
83	        }
84	        boolean international = telephone.trim().startsWith("+");
85	        String digits = telephone.replaceAll("\\D", "");
86	        if (!international) {
87	            if (digits.startsWith("0")) {
88	                digits = digits.substring(1);
89	            }
90	            digits = "61" + digits;
91	        }
92	        if (digits.length() < 8 || digits.length() > 15) {
93	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
94	        }
95	        org.springframework.samples.petclinic.service.E164NationalLength.check(digits);
96	        return "+" + digits;
