22	/**
23	 * Populates the derived registration fields on a newly created owner: its identifier,
24	 * counters and warnings computed against the existing owners. This keeps the enrichment as
25	 * one cohesive unit, separate from the request-handling concerns of the controller.
26	 */
27	public final class OwnerRegistration {
28	
29	    private OwnerRegistration() {
30	    }
31	
32	    public static void enrich(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
33	        owner.setNamesakeCount(NamesakeCounter.count(owners, owner));
34	        owner.setMemberId(MemberId.generate(owners, owner));
35	        owner.setBulkSignupWarning(BulkSignupWarning.isTriggered(owners));
36	        owner.setCapacityWarning(CityCapacity.isApproaching(owners, owner));
37	        owner.setHouseholdSize(HouseholdMatcher.householdSize(owners, owner));
38	        owner.setPossibleDuplicateOf(HouseholdMatcher.possibleDuplicateOf(owners, owner, sharesHousehold));
39	        owner.setMembershipLevel(HouseholdLevelCap.cap(owners, owner));
40	    }
41	}
