18	import java.time.LocalDate;
19	import java.util.Collection;
20	
21	import org.springframework.samples.petclinic.model.BusinessDay;
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Enforces the per-day owner cap: creation is blocked once
26	 * {@value #MAX_OWNERS_PER_DAY} owners already share today's registration date.
27	 */
28	public final class DailyRegistrationLimit {
29	
30	    public static final int MAX_OWNERS_PER_DAY = 100;
31	
32	    private DailyRegistrationLimit() {
33	    }
34	
35	    public static boolean isReached(Collection<Owner> existing) {
36	        LocalDate today = BusinessDay.adjust(LocalDate.now());
37	        long createdToday = existing.stream().filter(o -> today.equals(o.getRegistrationDate())).count();
38	        return createdToday >= MAX_OWNERS_PER_DAY;
39	    }
40	}
