16	package org.springframework.samples.petclinic.model;
17	
18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.util.Set;
21	
22	/**
23	 * Rolls a date forward onto a business day: weekends and listed public
24	 * holidays are skipped, landing on the next non-holiday weekday.
25	 */
26	public final class BusinessDay {
27	
28	    private static final Set<LocalDate> HOLIDAYS = Set.of(
29	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
30	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
31	            LocalDate.parse("2026-12-28"));
32	
33	    private BusinessDay() {
34	    }
35	
36	    private static boolean isBusinessDay(LocalDate date) {
37	        DayOfWeek dow = date.getDayOfWeek();
38	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
39	    }
40	
41	    public static LocalDate adjust(LocalDate date) {
42	        while (!isBusinessDay(date)) {
43	            date = date.plusDays(1);
44	        }
45	        return date;
46	    }
47	}
