31	/**
32	 * Renders business-rule rejections (e.g. 409 Conflict, 429 Too Many Requests) as an
33	 * RFC 7807 {@code application/problem+json} body carrying {@code type}, {@code title},
34	 * {@code status} and {@code detail}. Controllers only need to throw a
35	 * {@link RejectedRequestException}; the chosen status is preserved unchanged.
36	 */
37	@RestControllerAdvice
38	@Order(Ordered.HIGHEST_PRECEDENCE)
39	public class RejectedRequestAdvice {
40	
41	    @ExceptionHandler(RejectedRequestException.class)
42	    @ResponseBody
43	    public ResponseEntity<ProblemDetail> handleRejection(RejectedRequestException e, HttpServletRequest request) {
44	        HttpStatus status = e.getStatus();
45	        ProblemDetail detail = ProblemDetail.forStatus(status);
46	        detail.setType(URI.create(request.getRequestURL().toString()));
47	        detail.setTitle(status.getReasonPhrase());
48	        detail.setDetail(e.getMessage());
49	        return ResponseEntity.status(status).body(detail);
50	    }
51	
52	    /**
53	     * Signals that a request was rejected by a business rule, pairing the HTTP status to
54	     * return with a human-readable detail for the problem+json body.
55	     */
56	    public static class RejectedRequestException extends RuntimeException {
57	
58	        private final HttpStatus status;
59	
60	        public RejectedRequestException(HttpStatus status, String detail) {
61	            super(detail);
62	            this.status = status;
63	        }
64	
65	        public HttpStatus getStatus() {
66	            return this.status;
67	        }
68	    }
