25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * The single derived key that consolidates owner duplicate detection: the full SHA-256 hex of
29	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Because the telephone
30	 * is part of the key, two owners sharing a last name and postcode but using different telephones
31	 * yield different keys and are both allowed (surfacing instead as a soft match); a new owner is
32	 * rejected as a duplicate only when it collides with an existing owner on the whole key.
33	 */
34	public final class IdentityKey {
35	
36	    private IdentityKey() {
37	    }
38	
39	    public static String of(Owner owner) {
40	        String raw = IdentityRegion.v2(owner) + "|" + owner.getTelephone() + "|" + email(owner) + "|"
41	            + Soundex.of(owner.getLastName());
42	        return sha256hex(raw);
43	    }
44	
45	    public static boolean isDuplicate(Collection<Owner> owners, Owner owner) {
46	        String key = of(owner);
47	        return owners.stream().filter(o -> !Boolean.TRUE.equals(o.getDeleted()))
48	            .anyMatch(o -> key.equals(of(o)));
49	    }
50	
51	    private static String email(Owner owner) {
52	        return owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
53	    }
54	
55	    private static String sha256hex(String value) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
58	            return HexFormat.of().formatHex(digest);
59	        }
60	        catch (NoSuchAlgorithmException e) {
61	            throw new IllegalStateException(e);
62	        }
63	    }
64	}
