16	package org.springframework.samples.petclinic.service;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.HexFormat;
23	import java.util.Locale;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Detects owners that belong to the same household. The household is keyed on the
29	 * normalised last name and the postcode, so any two owners sharing those values belong
30	 * to the same household without coordination.
31	 */
32	public final class HouseholdMatcher {
33	
34	    private HouseholdMatcher() {
35	    }
36	
37	    /**
38	     * A stable identifier shared by every owner in the same household: the first 12 hex
39	     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}.
40	     */
41	    public static String householdId(Owner owner) {
42	        String key = IdentityRegion.v2(owner) + "|" + normalize(owner.getLastName()) + "|"
43	            + (owner.getPostcode() == null ? "" : owner.getPostcode());
44	        return hex12(key);
45	    }
46	
47	    /**
48	     * True when an existing owner already belongs to this owner's household and the owner
49	     * has not declared shared-household membership. A declared member (sharesHousehold) is
50	     * allowed through rather than rejected as a household duplicate.
51	     */
52	    public static boolean isHouseholdDuplicate(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
53	        return !Boolean.TRUE.equals(sharesHousehold)
54	            && owners.stream().filter(o -> !Boolean.TRUE.equals(o.getDeleted())).anyMatch(o -> sameHousehold(o, owner));
55	    }
56	
57	    /** The number of owners in this owner's household, counting the owner itself. */
58	    public static int householdSize(Collection<Owner> owners, Owner owner) {
59	        return (int) owners.stream().filter(o -> sameHousehold(o, owner)).count() + 1;
60	    }
61	
62	    /**
63	     * The id of an owner this one may soft-duplicate, or {@code null}. A declared household
64	     * member is never a suspected duplicate.
65	     */
66	    public static Integer possibleDuplicateOf(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
67	        return Boolean.TRUE.equals(sharesHousehold) ? null : PossibleDuplicateMatcher.matchId(owners, owner);
68	    }
69	
70	    private static boolean sameHousehold(Owner a, Owner b) {
71	        return householdId(a).equals(householdId(b));
72	    }
73	
74	    private static String hex12(String key) {
75	        try {
76	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
77	            return HexFormat.of().formatHex(digest, 0, 6);
78	        }
79	        catch (NoSuchAlgorithmException e) {
80	            throw new IllegalStateException(e);
81	        }
82	    }
83	
84	    private static String normalize(String value) {
85	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
86	    }
87	}
