23	/**
24	 * Caps a new owner's {@link MembershipLevel} at one above the current maximum level among
25	 * the other (non-deleted) members of their household. With no existing household member
26	 * the owner's own level applies unchanged.
27	 */
28	public final class HouseholdLevelCap {
29	
30	    private HouseholdLevelCap() {
31	    }
32	
33	    public static int cap(Collection<Owner> owners, Owner owner) {
34	        String householdId = HouseholdMatcher.householdId(owner);
35	        OptionalInt max = owners.stream()
36	            .filter(o -> !Boolean.TRUE.equals(o.getDeleted()))
37	            .filter(o -> householdId.equals(HouseholdMatcher.householdId(o)))
38	            .mapToInt(MembershipLevel::of)
39	            .max();
40	        int level = MembershipLevel.of(owner);
41	        return max.isPresent() ? Math.min(level, max.getAsInt() + 1) : level;
