18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.HashSet;
23	import java.util.Set;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Builds an owner's memberId formatted '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;&lt;CHK&gt;': the region code
29	 * derived from the postcode, the 2-digit fiscal year of the registrationDate, the first eight
30	 * upper-case hex characters of SHA-256 over the owner's normalized telephone concatenated with
31	 * the last name, and a single Luhn check digit over the digits of '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;'.
32	 */
33	public final class MemberId {
34	
35	    private MemberId() {
36	    }
37	
38	    public static String generate(Collection<Owner> existing, Owner owner) {
39	        String region = LocalityResolver.locality(owner.getCity(), owner.getPostcode());
40	        String base = region + FiscalYear.label(owner.getRegistrationDate()).substring(2)
41	            + hash8(IdentityRegion.v2(owner) + owner.getTelephone() + owner.getLastName());
42	        return deduplicate(base + CheckDigit.of(base), existing);
43	    }
44	
45	    private static String deduplicate(String candidate, Collection<Owner> existing) {
46	        Set<String> taken = new HashSet<>();
47	        for (Owner o : existing) {
48	            taken.add(o.getMemberId());
49	        }
50	        String unique = candidate;
51	        for (int n = 2; taken.contains(unique); n++) {
52	            unique = candidate + "-" + n;
53	        }
54	        return unique;
55	    }
56	
57	    private static String hash8(String value) {
58	        try {
59	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder hex = new StringBuilder();
61	            for (int i = 0; i < 4; i++) {
62	                hex.append(String.format("%02X", digest[i]));
63	            }
64	            return hex.toString();
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException(ex);
68	        }
69	    }
70	}
