11	public final class DisposableEmailDomain {
12	
13	    private static final Set<String> BLOCKED =
14	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
15	
16	    private DisposableEmailDomain() {
17	    }
18	
19	    public static String validate(String email) {
20	        if (email != null) {
21	            int at = email.lastIndexOf('@');
22	            if (at >= 0 && BLOCKED.contains(email.substring(at + 1).toLowerCase(Locale.ROOT))) {
23	                throw new IllegalArgumentException("Email domain is not allowed: " + email);
24	            }
25	        }
26	        return email;
27	    }
28	
29	    /**
30	     * True when the email's domain is disposable-adjacent: a subdomain of a known disposable
31	     * provider (e.g. {@code inbox.mailinator.com}). Exactly-blocked domains are rejected at
32	     * creation, so only these near-matches reach a saved owner. A {@code null} or domain-less
33	     * email is not adjacent.
34	     */
35	    public static boolean isDisposableAdjacent(String email) {
36	        if (email == null) {
37	            return false;
38	        }
39	        int at = email.lastIndexOf('@');
40	        if (at < 0) {
41	            return false;
42	        }
43	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
44	        return BLOCKED.stream().anyMatch(b -> domain.endsWith("." + b));
45	    }
