17	
18	import java.util.Locale;
19	
20	/**
21	 * Standard American Soundex: the first letter followed by three digits that phonetically
22	 * encode the remaining consonants. A {@code null} or letter-less name yields the empty
23	 * string, so two such names still share a code.
24	 */
25	public final class Soundex {
26	
27	    private Soundex() {
28	    }
29	
30	    public static String of(String name) {
31	        String letters = name == null ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
32	        if (letters.isEmpty()) {
33	            return "";
34	        }
35	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
36	        char prev = digit(letters.charAt(0));
37	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
38	            char d = digit(letters.charAt(i));
39	            if (d != '0' && d != prev) {
40	                code.append(d);
41	            }
42	            if (letters.charAt(i) != 'H' && letters.charAt(i) != 'W') {
43	                prev = d;
44	            }
45	        }
46	        while (code.length() < 4) {
47	            code.append('0');
48	        }
49	        return code.toString();
50	    }
51	
52	    private static char digit(char c) {
53	        return switch (c) {
54	            case 'B', 'F', 'P', 'V' -> '1';
55	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
56	            case 'D', 'T' -> '3';
57	            case 'L' -> '4';
58	            case 'M', 'N' -> '5';
59	            case 'R' -> '6';
60	            default -> '0';
61	        };
62	    }
63	}
